#include <iostream>
#include <algorithm>
using namespace std;

using ll = long long;

ll gcd(ll a, ll b) {
    return b ? gcd(b, a % b) : a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, x, y;
    while (cin >> a >> b >> x >> y) {
        ll g = gcd(x, y);
        x /= g;
        y /= g;

        ll k = min(a / x, b / y);
        cout << k * x << ' ' << k * y << '\n';
    }

    return 0;
}

